function icon(n,cl=''){return `<svg class="icon ${cl}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICO[n]||ICO.grid}</svg>`}
const app=document.querySelector('#app');
const navGroups=[['WORKSPACE',[['dashboard','Overview','grid'],['customers','Customers','users'],['orders','Sales orders','order'],['invoices','Invoices','receipt'],['payments','Payments','wallet'],['debts','Debt center','chart']]],['OPERATIONS',[['stock','Inventory','box'],['tankers','Tanker receipts','truck'],['pricing','Fuel pricing','trend'],['deliveries','Delivery sheets','clipboard'],['dispatches','Dispatches','repeat']]],['INSIGHTS',[['reports','Reports & exports','bars'],['audits','Activity log','clock']]],['ADMINISTRATION',[['team','Team & access','shield'],['settings','Settings','settings']]]];
