const money=n=>'$'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
const number=n=>Number(n).toLocaleString('en-US');
const chip=(s)=>{const t=String(s).toLowerCase();return `<span class="chip ${/active|paid|posted|fulfilled|complete|received|delivered|approved/.test(t)&&!/partially|unpaid/.test(t)?'success':/hold|partial|pending|transit|confirmed/.test(t)?'warning':/unpaid|overdue|cancel|revers/.test(t)?'danger':/draft|inactive/.test(t)?'neutral':'blue'}">${s}</span>`};
const button=(label,action='',kind='',ico='')=>`<button class="btn ${kind}" ${action?`data-action="${action}"`:''}>${ico?icon(ico):''}${label}</button>`;
const metrics=(data)=>`<div class="grid g${Math.min(data.length,5)}">${data.map((m,i)=>`<div class="panel metric ${m.dark?'dark':''}"><div class="metric-top"><span>${m.label}</span><span class="metric-icon">${icon(m.ico||'chart')}</span></div><div><div class="metric-num">${m.value}</div><div class="metric-meta">${m.change?`<span class="${m.down?'diff-down':'diff-up'}">${m.change}</span>`:''}${m.note||''}</div></div></div>`).join('')}</div>`;
function pageHead(title,desc='',actions='',kicker='WORKSPACE'){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1 class="page-title">${title}</h1><p class="page-sub">${desc}</p></div><div class="page-actions">${actions}</div></div>`}
function pnl(title,content,actions='',sub='',extra=''){return `<section class="panel ${extra}"><div class="panel-head"><div><div class="panel-title">${title}</div>${sub?`<div class="panel-sub">${sub}</div>`:''}</div><div class="panel-actions">${actions}</div></div>${content}</section>`}
function table(headers,rows,foot=''){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" style="text-align:center;padding:35px;color:var(--muted)">No matching records found</td></tr>`}</tbody></table></div>${foot?`<div class="table-foot"><span>${foot}</span><span class="row">${button('Previous','prev','btn-sm')}${button('Next','next','btn-sm')}</span></div>`:''}`}
function controls(placeholder='Search records...',options=[]){return `<div class="table-controls"><label class="row" style="flex:1;min-width:160px">${icon('search')}<input id="global-search" class="control search" value="${escapeHtml(state.search)}" placeholder="${placeholder}" aria-label="Search records" oninput="setSearch(this.value)"/></label>${options.length?`<select class="control select" id="filter-select" onchange="setFilter(this.value)"><option>All</option>${options.map(x=>`<option ${state.filter===x?'selected':''}>${x}</option>`).join('')}</select>`:''}${button('Filters','filters','btn-sm','filter')}</div>`}
function tabs(names){return `<div class="tabs no-print" role="tablist">${names.map(n=>`<button class="tab ${state.tab===n?'active':''}" data-tab="${n}" role="tab">${n}</button>`).join('')}</div>`}
function field(label,type='text',placeholder='',value='',id=''){return `<div class="form-field"><label class="field-label" ${id?`for="${id}"`:''}>${label}</label><input class="field-input" type="${type}" value="${escapeHtml(value)}" placeholder="${placeholder}" ${id?`id="${id}"`:''}/></div>`}
function selectField(label,opts,id=''){return `<div class="form-field"><label class="field-label">${label}</label><select class="field-input" ${id?`id="${id}"`:''}>${opts.map(o=>`<option>${o}</option>`).join('')}</select></div>`}
function details(info){return `<dl class="details-grid">${info.map(([k,v])=>`<div class="details-item"><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl>`}
function avatar(name){return `<span class="avatar">${name.split(' ').slice(0,2).map(x=>x[0]).join('')}</span>`}
function escapeHtml(str){return String(str??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\'':'&#39;','"':'&quot;'}[c]))}
function infoPair(a,b){return `<div class="info-pair"><span>${a}</span><strong>${b}</strong></div>`}
function bars(values=[35,50,62,46,77,65,90],lime=[19,28,35,29,46,50,60],labels=['Sat','Sun','Mon','Tue','Wed','Thu','Fri']){return `<div style="padding:5px 20px 21px"><div class="bar-chart">${values.map((v,i)=>`<div class="bar-wrap"><div class="bar-pair"><div class="bar" style="height:${v}%" title="Sales ${v}"></div><div class="bar lime" style="height:${lime[i]}%" title="Collections ${lime[i]}"></div></div><span class="bar-label">${labels[i]}</span></div>`).join('')}</div><div class="chart-caption"><span><i class="dot" style="background:var(--petrol)"></i> Invoice revenue</span><span><i class="dot" style="background:var(--lime)"></i> Collections</span></div></div>`}
function smallStats(items){return `<div class="grid g3">${items.map(([k,v])=>`<div style="padding:16px;background:#FAFCFA;border:1px solid var(--line);border-radius:10px"><div class="card-caption">${k}</div><div style="font-size:23px;font-weight:800;letter-spacing:-.7px;margin-top:9px">${v}</div></div>`).join('')}</div>`}
function stockTiles(){return `<div class="top-stock"><div class="fuel-stock"><div class="row-between"><span class="item-name">Diesel · Naafto</span>${icon('fuel')}</div><div class="fuel-num">34,850 <small>L</small></div><div class="progress"><div class="progress-fill" style="width:71%"></div></div><div class="row-between micro muted" style="margin-top:9px"><span>Warehouse</span><span>71% capacity</span></div></div><div class="fuel-stock"><div class="row-between"><span class="item-name">Petrol · Basiin</span>${icon('fuel')}</div><div class="fuel-num">18,420 <small>L</small></div><div class="progress"><div class="progress-fill" style="width:45%;background:var(--petrol)"></div></div><div class="row-between micro muted" style="margin-top:9px"><span>Warehouse</span><span>45% capacity</span></div></div></div>`}
function navItem(id,label,ico){return `<button class="nav-link ${state.page===id?'active':''}" data-nav="${id}">${icon(ico)}<span>${label}</span>${id==='deliveries'?'<span class="nav-count">4</span>':''}</button>`}
function shell(content){let crumb='Overview';for(const [,links] of navGroups){const found=links.find(v=>v[0]===state.page);if(found)crumb=found[1]}if(state.page==='customer-profile')crumb='Customer account';if(state.page==='customer-ledger')crumb='Customer statement';if(state.page==='new-order')crumb='New order';if(state.page==='reconcile')crumb='Reconciliation';if(state.page==='manifest')crumb='Delivery manifest';if(state.page==='receive')crumb='Receive tanker';if(state.page==='order-detail')crumb='Order detail';if(state.page==='invoice-detail')crumb='Invoice detail';if(state.page==='payment-detail')crumb='Payment detail';return `<div class="app-shell"><div class="sidebar-backdrop ${state.mobile?'show':''}" data-action="close-mobile"></div><aside class="sidebar ${state.mobile?'mobile-open':''}"><a href="#dashboard" class="brand" data-nav="dashboard"><div class="brand-mark">f.</div><div><div class="brand-name">fueldesk<span style="color:var(--lime)">.</span></div><div class="brand-sub">Wholesale workspace</div></div></a><div class="nav-wrap">${navGroups.map(([label,links])=>`<div class="nav-label">${label}</div>${links.map(l=>navItem(...l)).join('')}`).join('')}</div><div class="sidebar-foot"><div class="user-card"><span class="avatar">MA</span><div style="flex:1"><b>Mohamed A.</b><small>Owner · Demo workspace</small></div><button aria-label="Sign out" title="Sign out" class="btn btn-quiet btn-icon" style="color:#ADC8C1" data-nav="login">${icon('logout')}</button></div></div></aside><div class="shell-main"><header class="topbar"><div class="crumb"><button class="btn btn-icon btn-quiet mobile-nav" data-action="toggle-mobile" aria-label="Open navigation">${icon('menu')}</button><span>Workspace</span>${icon('chevr')}<strong>${crumb}</strong></div><div class="top-actions"><span class="demo-badge">UI DEMO</span><span class="today-badge"><span class="status-online"></span>Friday, 09 October 2026</span><button class="top-icon" aria-label="Notifications" data-action="notifications">${icon('clock')}</button><span class="top-profile">MA</span></div></header><main class="workarea">${content}</main></div></div>`}
function login(){return `<div class="login-screen"><div class="login-shell"><div class="login-brand"><div class="brand-mark">f.</div><div style="margin-left:11px"><div class="brand-name" style="color:var(--petrol)">fueldesk<span style="color:#79AF23">.</span></div><div class="brand-sub">Wholesale workspace</div></div></div><div class="login-panel"><div class="login-accent"></div><div class="eyebrow" style="margin-bottom:13px">ACCOUNT ACCESS</div><h1>Welcome back</h1><p class="sub">Sign in to manage customers, stock and daily transactions.</p><form id="login-form"><div class="form-field"><label class="field-label" for="login-email">Email address</label><input class="field-input" type="email" id="login-email" value="owner@fueldesk.so" autocomplete="username" required/></div><div class="form-field"><label class="field-label" for="login-password">Password</label><input class="field-input" type="password" id="login-password" placeholder="Enter your password" autocomplete="current-password" required/></div><div class="login-help"><label><input type="checkbox" checked/> Remember this device</label><span>Owner & office staff only</span></div><button class="btn btn-lime" type="submit">Sign in to workspace ${icon('arrow')}</button></form><div class="login-demo">${icon('info')} <b>Design preview:</b> Any password opens the local UI prototype. No authentication or backend is connected.</div></div><div class="login-bottom">A focused workspace for fuel wholesale operations · 2026</div></div></div>`}
function dashboard(){return `${pageHead('Good afternoon, Mohamed.','Here is where your fuel business stands today.',`${button('Last 30 days','range','', 'calendar')}${button('Create order','new-order','btn-lime','plus')}`,'FRIDAY · 09 OCTOBER 2026')}
${metrics([{label:'Invoiced sales',value:'$48,920',ico:'chart',change:'+12.4%',note:'vs previous period'},{label:'Customer debt',value:'$12,640',ico:'wallet',note:'Across 8 open accounts'},{label:'Collected payments',value:'$36,280',ico:'receipt',change:'+8.1%',note:'vs previous period'},{label:'Active deliveries',value:'04',ico:'truck',note:'Awaiting confirmation',dark:true}])}
<div class="grid g3 section-space"><div class="panel span2">${pnlContent('Sales & collections',bars(),`${button('View reports','reports','btn-sm','arrow')}`,'Money received is shown separately from invoiced revenue.')}</div><div class="panel">${pnlContent('Fuel on hand',stockTiles(),`${button('Inventory','stock','btn-sm','arrow')}`,'Current warehouse stock, excluding in-transit fuel.')}</div></div>
<div class="grid g3 section-space"><div class="panel span2">${pnlContent('Orders requiring attention',table(['Order','Customer','Fuel / units','Amount','Status',''],state.orders.slice(0,4).map(o=>`<tr><td><strong>${o.id}</strong></td><td>${o.customer}</td><td>${o.type} <span class="muted">· ${o.qty} fuusto</span></td><td class="money">${money(o.total)}</td><td>${chip(o.status)}</td><td>${button('Open','order-detail','btn-sm','arrow')}</td></tr>`).join('')) ,`${button('All orders','orders','btn-sm','arrow')}`,'Today’s confirmed orders and outstanding dispatches.')}</div><div class="panel">${pnlContent('Daily priorities',`<div style="padding:0 22px 19px">${[
 ['04','Deliveries awaiting reconciliation','dispatches'],['06','Invoices pending collection','debts'],['02','Unbilled accepted deliveries','invoices'],['01','Price update scheduled','pricing']].map(([n,t,to])=>`<div class="list-item row-between"><div class="row"><span style="display:grid;place-items:center;width:31px;height:31px;background:#EFF6E9;border-radius:8px;font-weight:800;color:var(--petrol)">${n}</span><span style="font-size:11px;font-weight:650">${t}</span></div><button class="btn btn-quiet btn-icon" data-nav="${to}" aria-label="Open ${t}">${icon('chevr')}</button></div>`).join('')}</div>`,'','What needs attention next.')}</div></div>`}
function pnlContent(title,content,actions='',sub=''){return `<div class="panel-head"><div><div class="panel-title">${title}</div><div class="panel-sub">${sub}</div></div><div class="panel-actions">${actions}</div></div>${content}`}
